-- mod-subclass: which aura shows a weapon display in the Two-Headed Ogre's hand.

DROP TABLE IF EXISTS `mod_subclass_held_weapon`;
CREATE TABLE `mod_subclass_held_weapon` (
    `DisplayId` INT UNSIGNED NOT NULL,
    `SpellId` INT UNSIGNED NOT NULL,
    PRIMARY KEY (`DisplayId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
